Definition chx_out (E0 E' : ecv) : Prop :=
  E' = E0
  \/ (ec_cat E' = AG_HTTP_CAT /\ (ec_val E' = HE_NEED_MORE \/ ec_val E' = HE_BAD_CHUNK_EXTENSION)
      /\ 2 <= ec_flags E' /\ Z.odd (ec_flags E') = true /\ ec_ok E').

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Definition CHX_STACK : Z := 112 + AASSIGN_STACK.     (* [comment removed for export] *)

Definition chx_W (lo : Z) (sp : word) (I E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (I, I + 8); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z.

Definition chx_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (it0 I E lo shi : Z) (bs : list byte) (E0 : ecv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' it' E' g',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (chx_W lo sp I E) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ bytes_at bsegs m' it0 bs
    /\ rw_cells bsegs m' I [C8 (wz it')] /\ it0 <= it' <= it0 + Z.of_nat (length bs)
    /\ rw_cells bsegs m' E (ErrCodeCells E') /\ chx_out E0 E'
    /\ AHttpCat m' g' /\ AXStatics m'
    /\ ACONST m' /\ stack0 m' lo shi.                                  (* [comment removed for export] *)

(* [comment removed for export] *)
Definition chx_pure (sp : word) (it0 I E lo shi : Z) (bs : list byte) (E0 : ecv) : Prop :=
  ec_ok E0 /\ lo + CHX_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ aapp it0 (Z.of_nat (length bs)) /\ it0 + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= I /\ I + 8 <= shi /\ I mod 8 = 0
  /\ aapp E 24 /\ E mod 8 = 0
  /\ (it0 + Z.of_nat (length bs) <= E \/ E + 24 <= it0)
  /\ bv_unsigned sp mod 16 = 0 /\ bv_unsigned sp + 64 <= shi.

Definition chx_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (it0 I E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool),
  bytes_at bsegs m it0 bs ->
  rw_cells bsegs m I [C8 (wz it0)] ->
  rw_cells bsegs m E (ErrCodeCells E0) ->
  AHttpCat m g -> AXStatics m ->
  stk bsegs m lo (bv_unsigned sp) ->
  chx_pure sp it0 I E lo shi bs E0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> stack0 m lo shi ->
  accessible m it0 (Z.of_nat (length bs)) -> accessible m E 24 -> shvis m E (E + 24) ->
  evt bsegs (chx_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc it0 I E lo shi bs E0 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz I) (wz (it0 + Z.of_nat (length bs))) (wz E) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_BP_PARSE_CHUNK_EXT) fc None m (seg_rom bsegs)).

