Lemma chx_side_elim : forall m it0 E lo shi n, chx_side m it0 E lo shi n ->
  ACONST m /\ stack0 m lo shi /\ AXStatics m /\ accessible m it0 n /\ accessible m E 24 /\ shvis m E (E + 24).
Proof.
  intros m it0 E lo shi n S. split; [exact (pside_aconst _ _ _ _ _ S)|]. split; [exact (pside_stack0 _ _ _ _ _ S)|].
  split; [exact (pside_statics _ _ _ _ _ S)|].
  split; [apply (pside_acc _ _ _ _ _ it0 n S); left; reflexivity|].
  split; [apply (pside_acc _ _ _ _ _ E 24 S); right; left; reflexivity|].
  apply (pside_shvis _ _ _ _ _ E 24 S). left. reflexivity.
Qed.

Lemma chx_pwin : forall sp it0 I E lo shi bs E0, chx_pure sp it0 I E lo shi bs E0 -> Forall pwin (chx_W lo sp I E).
Proof.
  intros sp it0 I E lo shi bs E0 (EOK & LO & CEIL & APP & QHI & ILO & IHI & IAL & APE & EAL & DQE & SPAL & SHI).
  unfold chx_W, CHX_STACK, AASSIGN_STACK, AINTRIN_STACK in *.
  repeat apply Forall_cons; [| | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - apply pwin_stack. clear - CEIL LO ILO. lia.
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

(* [comment removed for export] *)
Lemma chx_side_now : forall m m1 sp it0 I E lo shi bs E0,
  chx_side m it0 E lo shi (Z.of_nat (length bs)) -> munch (chx_W lo sp I E) m m1 -> wmono bsegs m m1 ->
  chx_pure sp it0 I E lo shi bs E0 ->
  ACONST m1 /\ stack0 m1 lo shi /\ AXStatics m1 /\ accessible m1 it0 (Z.of_nat (length bs)) /\ accessible m1 E 24 /\ shvis m1 E (E + 24).
Proof.
  intros m m1 sp it0 I E lo shi bs E0 S MU WM PURE. apply chx_side_elim.
  eapply pside_transport; [exact S| exact MU| exact WM| eapply chx_pwin; exact PURE].
Qed.

(* [comment removed for export] *)
Lemma chx_cat_now : forall m m1 (sp : word) I lo g,
  AHttpCat m g -> munch [(lo, bv_unsigned sp); (I, I + 8)]%Z m m1 -> wmono bsegs m m1 ->
  aceil <= lo -> bv_unsigned sp <= I -> lo <= bv_unsigned sp -> AHttpCat m1 g.
Proof.
  intros m m1 sp I lo g HC MU WM CEIL ILO LO. pose proof aceil_facts as (AF1 & _).
  eapply AHttpCat_transport; [exact HC| exact MU| exact WM| |];
    cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; repeat split; lia.
Qed.

