Definition chx_ctx (m m1 : mem) (sp s0v s1v s2v s3v s4v s5v s6v s7v s8v rav : word) (it0 I E lo shi : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool)
    (j8 junk : list byte) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -112) [CB 8 j8]
  /\ rw_cells bsegs m1 (bv_unsigned sp + -104) [CB 24 junk]
  /\ rw_cells bsegs m1 (bv_unsigned sp + -80) [C8 s8v; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells bsegs m1 I [C8 (wz itv)]
  /\ rw_cells bsegs m1 E (ErrCodeCells E0)
  /\ stk bsegs m1 lo (bv_unsigned sp + -112)
  /\ bytes_at bsegs m1 it0 bs
  /\ munch (chx_W lo sp I E) m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ munch [(lo, bv_unsigned sp); (I, I + 8)]%Z m m1
