(* [comment removed for export] *)
Definition chx_exitA_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5x s6x s7x s8x s0v s1v s2v s3v s4v s5v s6v s7v s8v s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo shi : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool) (j8 junk : list byte),
  chx_ctx m m1 sp s0v s1v s2v s3v s4v s5v s6v s7v s8v ra it0 I E lo shi bs itv E0 g j8 junk -> chx_pure sp it0 I E lo shi bs E0 ->
  it0 <= itv <= it0 + Z.of_nat (length bs) ->
  evt bsegs (chx_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9 s10 s11 F fc it0 I E lo shi bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz E) (wz ASHADOW_BASE) a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8x s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).

Local Ltac chx_exitA_tac e loc :=
  unfold chx_exitA_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5x s6x s7x s8x s0v s1v s2v s3v s4v s5v s6v s7v s8v s9 s10 s11 t3 t4 t5 t6
    F fc m m1 it0 I E lo shi bs itv E0 g j8 junk;
  intros CTX PURE ITV;
  destruct CTX as (FR0 & TMP & FRhi & IT & EC & ST & WIN & MU & WM & MI & MU2 & HC & SIDE);
  pose proof PURE as PURE';
  destruct PURE' as (EOK & LO & CEIL & APP & QHI & ILO & IHI & IAL & APE & EAL & DQE & SPAL & SHI);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof (aapp_bounds _ _ APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  (* [comment removed for export] *)
  pose proof (chx_cat_now _ _ _ _ _ _ HC MU2 WM CEIL ILO ltac:(unfold CHX_STACK, AASSIGN_STACK, AINTRIN_STACK in LO; lia)) as HC1;
  clear MU2 HC;
  destruct (chx_side_now _ _ _ _ _ _ _ _ _ _ SIDE MU WM PURE) as (AC1 & SK1 & XS1 & _);
  pose proof (stack0_bounds _ _ _ SK1) as [SKB1 SKB2];
  (* [comment removed for export] *)
  assert (D8 : (bv_unsigned sp + -104) mod 8 = 0) by (clear - SPAL; Z.div_mod_to_equations; lia);
  clear IAL APP SPAL AF2 AF3 EB5 PB5 EOK; hydeL DQE; hydeL EAL; hydeL D8;
  unfold chx_W, CHX_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP in *;
  unfold ErrCodeCells in EC;
  unfold wz; rewrite ASHADOW_BASE_val;
  (* [comment removed for export] *)
  step; step; step; step;
  let AS := fresh "AS" in
  pose proof ASSIGNA as AS;
  unfold aassignA_stmt, aassign_stmt, aassign_post, aassign_W, P_A_EC_CTOR_HTTP, AG_HTTP_CAT, AASSIGN_STACK, AINTRIN_STACK in AS;
  callZc (AS _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ (bv_unsigned sp + -104) e lo shi g junk) (clear TMP ST AS);
  [ exact TMP | exact HC1 | exact XS1 | rewrite ?unsigned_lit by lia; exact ST
  | rewrite ?unsigned_lit by lia; lia | lia | rewrite ?unsigned_lit by lia; lia | lia
  | exact D8 | lia
  | exact MI | exact AC1 | exact SK1 | rewrite ?unsigned_lit by lia; lia | ];
  clear AC1 SK1 XS1 HC1 D8;
  lazymatch goal with
  | TMP2 : rw_cells _ ?m2 (bv_unsigned sp + -104) (ErrCodeCells _), HC2 : AHttpCat ?m2 true,
    AC2 : ACONST ?m2, SK2 : stack0 ?m2 lo shi, ST2 : stk _ ?m2 lo _, MU' : munch _ m ?m2, WM' : wmono _ m ?m2 |- _ =>
    let AE2 := fresh "AE2" in let SV2 := fresh "SV2" in let KF := fresh "KF" in
    let TMPa := fresh "TMPa" in let TMPb := fresh "TMPb" in let ECa := fresh "ECa" in let ECb := fresh "ECb" in
    let SRC := fresh "SRC" in let DST := fresh "DST" in let junk16 := fresh "junk16" in
    let MU3 := fresh "MU3" in let WM3 := fresh "WM3" in
    (* [comment removed for export] *)
    destruct (chx_side_now m m2 sp it0 I E lo shi bs E0 SIDE
                ltac:(unfold chx_W, AG_HTTP_CAT; exact MU') WM' PURE) as (_ & _ & _ & _ & AE2 & SV2);
    (* [comment removed for export] *)
    unfold ErrCodeCells, EC_http, ec_make in TMP2; cbn [ec_val ec_cat ec_flags Z.eqb] in TMP2; unfold AG_HTTP_CAT, wz in TMP2;
    step; step; step; if_cases KF; zify_cond KF; [exfalso; clear - KF; lia|];
    (* [comment removed for export] *)
    zstep; change (Z.land 3 1) with 1; step; step; zstep;
    replace (Z.lor 1 loc) with (loc + 1) by (vm_compute; reflexivity);
    (* [comment removed for export] *)
    step; step; step; step;
    split_frameA TMP2 [C8 (Z_to_bv 64 e); C8 (Z_to_bv 64 6684368)] [C8 (Z_to_bv 64 3)] TMPa TMPb;
    pose proof (rw_cells_bytes_at _ _ _ _ TMPa) as SRC; cbn [cells_bytes cbytes app] in SRC; rewrite app_nil_r in SRC;
    split_frameA EC [C8 (Z_to_bv 64 (ec_val E0)); C8 (Z_to_bv 64 (ec_cat E0))] [C8 (Z_to_bv 64 (ec_flags E0))] ECa ECb;
    destruct (rw_cells_forget _ _ _ _ ECa) as [junk16 DST]; clear ECa; cbn [cells_size csize Nat.add] in DST;
    pose proof (munch_refl [(lo, bv_unsigned sp); (E, E + 24)]%Z m2) as MU3; pose proof (wmono_refl bsegs m2) as WM3;
    let MC := fresh "MC" in
    pose proof MEMCPY as MC; unfold asan_memcpy_stmt, amemcpy_stmt_at, amemcpy_post, AASAN_MEMCPY, AINTRIN_STACK in MC;
    callZc (MC _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ m2 (le8 (Z_to_bv 64 e) ++ le8 (Z_to_bv 64 6684368)) junk16 lo)
           (clear DST ST2 SRC MC);
    [ rewrite ?unsigned_lit by lia; exact SRC
    | rewrite ?unsigned_lit by lia; rewrite length_app, !length_le8; reflexivity
    | rewrite ?unsigned_lit by lia; exact DST
    | rewrite ?unsigned_lit by lia; lia
    | rewrite ?unsigned_lit by lia; eapply stack0_accessible; [exact SK2| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply accessible_sub; [exact AE2| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply stack0_shvis; [exact SK2| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply shvis_sub; [exact SV2| lia| lia| lia| lia| lia]
    | rewrite ?unsigned_lit by lia; exact ST2
    | lia
    | rewrite ?unsigned_lit by lia; lia
    | assumption
    | exact AC2
    | rewrite ?unsigned_lit by lia; lia
    | rewrite ?unsigned_lit by lia; eapply stack0_in_app_mem; [exact SK2| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply aapp_in_app_mem; [exact APE| lia| lia]
    | rewrite ?unsigned_lit by lia; eapply aconst_ok_aapp; [exact APE| lia| lia]
    | rewrite ?unsigned_lit by lia; left; lia
    | rewrite ?unsigned_lit by lia; right; lia
    | ];
    clear SK2 AC2 AE2 SV2;
    lazymatch goal with
    | DST3 : rw_cells _ ?m3 E [CB _ _], MU'' : munch _ m ?m3, WM'' : wmono _ m ?m3 |- _ =>
      let AE3 := fresh "AE3" in let RD := fresh "RD" in let HC3 := fresh "HC3" in
      destruct (chx_side_now m m3 sp it0 I E lo shi bs E0 SIDE
                  ltac:(unfold chx_W, AG_HTTP_CAT; exact MU'') WM'' PURE) as (_ & _ & _ & _ & AE3 & _);
